"""Content of STANDARD_MODEL_PROVENANCE (Markdown + LaTeX): where every result of sections 17-19 of 7+1.nb comes from, the
data used (with their sources), the decisions taken, the derivations, and the verification record.  Self-contained: every
equation used is written here."""
from docgen import Doc
from doc_stage3_common import fmt
from doc_sm import compare, max_rel


def build(D, today, runs):
    ck = D['checks']['sm']; refd = D['ref'].get('sm', ('', '', {})); ref = refd[2]
    nck = len(ck); nok = sum(1 for c in ck if c[1] == 'True')
    rb = [(k, v) for k, v in ref.items() if v in ('True', 'False')]
    d = Doc('The Standard Model on the world brane of 7+1 spacetime: provenance',
            'Sources, data, decisions, derivations and the verification record of the Standard Model on the brane, the portals of '
            'dirac16complex and neutrino flavour conversion — sections 17–19 of the notebook 7+1.nb',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1)', 'Document generated by tools/make_docs.py on ' + today],
            'This record states what was asked, which experimental data were used and where they come from, every decision taken with '
            'the equation behind it, how each result was derived and how it was checked: the %d checks of sections 17–19 of 7+1.nb (%d '
            'True), the %d boolean checks of the independent Python program tools/ref_sm.py (%d True), the comparison of every number '
            'printed by both programs, and the SHA-256 hashes of the files.' % (nck, nok, len(rb), sum(1 for k, v in rb if v == 'True')))

    d.h1('1. The task')
    d.p('This stage of the project asked (summarized; the original wording is the author’s private working material) for the TOTALITY of the '
        'Standard Model together with gravity and the field dirac16complex on the 7+1 spacetime of this project (one time coordinate $x_0$, '
        'seven space coordinates $x_1,\\dots,x_7$), following the ideas of the repository github.com/once-ere/Dirac_claude — there the Standard '
        'Model lives on a seven-dimensional fold of a 4+4 spacetime — but not its metric. Here the Standard Model lives on the 3+1-dimensional '
        'world brane $x_4=\\dots=x_7=0$, the auxiliary coordinates form a torus, and gravity and dirac16complex live in the whole spacetime. '
        'Every documentation file has a companion provenance file and a symbol file, in Markdown and LaTeX with PDFs; no document refers the '
        'reader to another one, and every equation used is written in the document that uses it.')

    d.h1('2. Data and their sources')
    d.table(['quantity', 'value used', 'source'], [
        ['$G_F$', '$1.1663788\\times10^{-5}$ GeV$^{-2}$', 'PDG 2025'],
        ['$m_W$, $m_Z$, $m_H$', '80.3692, 91.1880, 125.20 GeV', 'PDG 2025'],
        ['CKM: $s_{12}$, $s_{13}$, $s_{23}$, $\\delta$', '0.22501, 0.003732, 0.04183, 1.147', 'PDG 2024 (CKM review, global fit)'],
        ['$J$, $A$, $\\bar\\rho$, $\\bar\\eta$ (for comparison)', '$(3.12^{+0.13}_{-0.12})\\times10^{-5}$; $0.826\\pm0.016$; $0.1591\\pm0.0094$; $0.3523\\pm0.0073$', 'PDG 2024'],
        ['$m_u$, $m_d$, $m_s$', '2.16, 4.70, 93.5 MeV ($\\overline{\\rm MS}$, 2 GeV)', 'PDG 2025'],
        ['$m_c$, $m_b$, $m_t$', '1.2730 GeV, 4.183 GeV ($\\overline{\\rm MS}$), 172.56 GeV (direct)', 'PDG 2025'],
        ['$\\sin^2\\theta_{12}$, $\\sin^2\\theta_{23}$, $\\sin^2\\theta_{13}$, $\\delta$', '0.307, 0.561, 0.02195, 177°', 'NuFit-6.0, normal ordering, without SK atmospheric data'],
        ['$\\Delta m^2_{21}$, $\\Delta m^2_{31}$', '$7.49\\times10^{-5}$, $2.534\\times10^{-3}$ eV²', 'NuFit-6.0 (same set)'],
        ['$H_0$, $\\Omega_m$, $\\Omega_r$', '67.4 km/s/Mpc, 0.315, $9.14\\times10^{-5}$', 'Planck 2018 ($t_0=13.787\\pm0.020$ Gyr for comparison)'],
        ['$M_{\\rm Pl}$ (reduced)', '$2.435\\times10^{18}$ GeV', 'standard value'],
        ['$\\hbar c$', '$1.973269804\\times10^{-16}$ GeV m', 'CODATA'],
        ['$N_A$', '$6.02214076\\times10^{23}$ mol$^{-1}$', 'SI (exact)'],
        ['$T_\\gamma$', '2.7255 K', 'CMB temperature (Fixsen 2009)'],
        ['$k_B$', '$8.617333262\\times10^{-5}$ eV/K', 'SI (exact)'],
        ['$R_\\odot$; $n_e(r)$', '$6.957\\times10^8$ m; $245N_Ae^{-10.54r/R_\\odot}$ cm$^{-3}$', 'IAU nominal radius; exponential fit to the standard solar model (Bahcall 1989)'],
        ['DUNE: $L$, $E$, $\\rho$, $Y_e$', '1300 km, 2.5 GeV, 2.848 g/cm³, 0.5', 'DUNE design baseline and crust density'],
    ], widths=[0.3, 0.38, 0.32], small=True)
    d.p('Full references: S. Navas et al. (Particle Data Group), Phys. Rev. D 110 (2024) 030001 and the 2025 update (pdg.lbl.gov); I. Esteban, '
        'M. C. Gonzalez-Garcia, M. Maltoni, I. Martinez-Soler, J. P. Pinheiro, T. Schwetz, JHEP 12 (2024) 216 (NuFit-6.0); Planck Collaboration, '
        'Astron. Astrophys. 641 (2020) A6; D. J. Fixsen, Astrophys. J. 707 (2009) 916; J. N. Bahcall, *Neutrino Astrophysics* (Cambridge, 1989).')
    vv = D.get('versions', {})
    d.p('Software: Wolfram Language 15.0.1 (front end WolframNB.exe); Python %s with numpy %s, scipy %s, sympy %s.' % (
        vv.get('python', '?'), vv.get('numpy', '?'), vv.get('scipy', '?'), vv.get('sympy', '?')))

    d.h1('3. Decisions')
    d.table(['#', 'decision', 'reason / equation'], [
        ['1', 'the Standard Model lives on the brane $W=\\lbrace y=0\\rbrace$ of a torus $T^4$ of the auxiliary coordinates', 'the 7+1 analogue of the fold of Dirac_claude; $\\int_Wd^4x\\sqrt{|h|}=\\int d^8X\\sqrt{|g|}\\,\\delta^4(y)/b^4$'],
        ['2', 'three generations with right-handed neutrinos (Dirac neutrinos)', 'anomalies cancel with or without $\\nu_R$; $\\nu_R$ gives Dirac masses $m=yv/\\sqrt2$'],
        ['3', 'tree-level electroweak relations with the on-shell weak angle', '$\\cos\\theta_W=m_W/m_Z$ makes $\\rho=m_W^2/(m_Z^2\\cos^2\\theta_W)=1$ exactly'],
        ['4', 'standard parametrization of both mixing matrices', '$U=R_{23}U_{13}(\\delta)R_{12}$; Yukawa matrices in the basis where the up-type (charged-lepton) Yukawa is diagonal'],
        ['5', 'lightest neutrino massless, normal ordering', 'the oscillation data fix only $\\Delta m^2_{ij}$'],
        ['6', 'brane decomposition with the Dirac representation and $\\rho_4=i\\gamma_0$, $\\rho_k=-\\gamma_{k-4}$ ($k=5,6,7$)', 'gives anti-Hermitian $\\rho_k$ with $\\lbrace\\rho_k,\\rho_l\\rbrace=-2\\delta_{kl}$, so $R_k=\\gamma_5\\otimes\\rho_k$ squares to $-1$'],
        ['7', 'the intertwiner by a Schur average', '$\\sum_K\\Gamma^{(K)}s(R^{(K)})^{-1}$ commutes in the sense $\\Gamma_AU=UR_A$ for any $s$; non-zero for a suitable matrix unit $s$'],
        ['8', 'portals are invented couplings at the brane, separate for the two chiral halves', 'as in Dirac_claude; they are the only contact between dirac16complex and the Standard Model besides gravity'],
        ['9', 'neutrino evolution in matter by the exponential of the constant-density Hamiltonian; the Sun by direct integration of the two-flavour equation', 'exact for constant density; checked against the adiabatic formula'],
        ['10', 'the solar two-flavour Hamiltonian uses the effective potential $c_{13}^2V_{CC}$ and $P_{ee}=c_{13}^4P^{(2)}_{ee}+s_{13}^4$', 'standard reduction of three flavours when $\\Delta m^2_{31}\\gg2EV$'],
    ], widths=[0.055, 0.475, 0.47], small=True)

    d.h1('4. Derivations')
    d.p('**Anomaly sums** (one generation, left-handed $+$, right-handed $-$):')
    d.align([r'A_{SU(3)^2U(1)}&=2\cdot\tfrac16-\tfrac23+\tfrac13=0,\qquad A_{SU(2)^2U(1)}=3\cdot\tfrac16-\tfrac12=0,\qquad A_{SU(3)^3}=2-1-1=0,',
             r'A_{U(1)^3}&=6\big(\tfrac16\big)^3-3\big(\tfrac23\big)^3-3\big(-\tfrac13\big)^3+2\big(-\tfrac12\big)^3-(-1)^3=\tfrac1{36}-\tfrac89+\tfrac19-\tfrac14+1=0,',
             r'A_{\rm grav^2U(1)}&=6\cdot\tfrac16-3\cdot\tfrac23-3\cdot\big(-\tfrac13\big)+2\cdot\big(-\tfrac12\big)-(-1)=0 .'])
    d.p('**Gauge-boson masses.** With $\\langle\\Phi\\rangle=(0,v/\\sqrt2)$:')
    d.eq(r"\big|D_\mu\langle\Phi\rangle\big|^2=\frac{v^2}8\Big[g^2\big((W^1)^2+(W^2)^2\big)+\big(gW^3-g'B\big)^2\Big],")
    d.p('whose Hessian in $(W^1,W^2,W^3,B)$ has the eigenvalues $g^2v^2/4$ (twice), $(g^2+g\'^2)v^2/4$ and $0$.')
    d.p('**Brane bilinears.** $\\Gamma_AU=UR_A$ and $U^\\dagger U=1$ give $\\bar\\psi\\Gamma^\\mu\\psi\'=\\psi^\\dagger\\Gamma_0\\Gamma^\\mu\\psi\'=\\zeta^\\dagger R_0R^\\mu\\zeta\'$, and '
        '$R_0R^\\mu=(\\gamma_0\\gamma^\\mu)\\otimes1_4$ for $\\mu=0,\\dots,3$, so the transverse index $a$ is summed: $\\sum_a\\bar\\psi_a\\gamma^\\mu\\psi\'_a$.')
    d.p('**Kaluza–Klein masses.** $X=\\gamma_5\\otimes\\vec\\rho\\cdot\\vec q/b_0$ anticommutes with $\\gamma_\\mu\\otimes1_4$ ($\\gamma_5$ anticommutes with $\\gamma_\\mu$) '
        'and $X^2=\\gamma_5^2\\otimes(\\vec\\rho\\cdot\\vec q)^2/b_0^2=-|\\vec q|^2/b_0^2$; then $(\\gamma\\cdot p\\otimes1+X)^2=(p^2-|\\vec q|^2/b_0^2)\\,1$, so the '
        'operator $\\gamma\\cdot p\\otimes1+X-m$ is singular exactly when $p^2=m^2+|\\vec q|^2/b_0^2$.')
    d.p('**Non-unitary mixing.** For $\\mathcal M=\\begin{pmatrix}m_D&\\mu\\\\0&m1_4\\end{pmatrix}$ with $m\\gg\\mu,m_D$ the left singular vectors give, to '
        'second order in $\\mu/m$, $N=(1-\\tfrac12\\mu\\mu^\\dagger/m^2)U$, hence $1-NN^\\dagger=\\mu\\mu^\\dagger/m^2$.')
    d.p('**Vacuum oscillations.** Expanding $|\\sum_iU_{\\beta i}U^*_{\\alpha i}e^{-im_i^2L/(2E)}|^2$ and using unitarity, $\\sum_iU_{\\beta i}U^*_{\\alpha i}=\\delta_{\\alpha\\beta}$:')
    d.eq(r'P(\alpha\to\beta)=\delta_{\alpha\beta}-4\sum_{i>j}\mathrm{Re}\,X_{ij}\sin^2\Delta_{ij}+2\sum_{i>j}\mathrm{Im}\,X_{ij}\sin2\Delta_{ij},\qquad X_{ij}=U^*_{\alpha i}U_{\beta i}U_{\alpha j}U^*_{\beta j}.')
    d.p('(An earlier version of the notebook used $X_{ij}=U_{\\alpha i}U^*_{\\beta i}U^*_{\\alpha j}U_{\\beta j}$, the complex conjugate, which flips the sign of the '
        'CP-odd term; it was corrected, and the check compares the formula with the direct evolution for all nine $(\\alpha,\\beta)$.)')
    d.p('**MSW angle.** Diagonalizing $\\frac{\\Delta m^2}{4E}\\begin{pmatrix}-\\cos2\\theta&\\sin2\\theta\\\\\\sin2\\theta&\\cos2\\theta\\end{pmatrix}+\\mathrm{diag}(V,0)$ gives '
        '$\\tan2\\theta_m=\\sin2\\theta/(\\cos2\\theta-2EV/\\Delta m^2)$.')

    d.h1('5. Verification')
    lg = D.get('log', {})
    d.p('**Evaluation of 7+1.nb**: Wolfram %s; finished %s; message cells %s. The checks of sections 17–19:' % (
        lg.get('version', '15.0.1'), lg.get('finished', '?'), lg.get('message cells', '?')))
    d.table(['#', 'check', 'result', 'section'],
            [[str(i + 1), '`' + c[0].replace('`', "'") + '`', c[1], (c[3][:4] if c[3] else c[2][:3])] for i, c in enumerate(ck)],
            widths=[0.055, 0.745, 0.08, 0.12], small=True)
    d.p('**The independent Python program** tools/ref_sm.py — its boolean checks:')
    d.table(['#', 'check', 'result'], [[str(i + 1), '`' + k.replace('`', "'") + '`', v] for i, (k, v) in enumerate(rb)],
            widths=[0.055, 0.825, 0.12], small=True)
    d.p('**Numbers printed by both programs** (relative differences; the Python program prints $|V|$ with 6 and $|U|$ with 5 decimals):')
    rows = []
    for lab, a, b, note in compare(D):
        r = max_rel(a, b)
        rows.append([lab, str(len(a)), fmt(r, 2) if r is not None else '—'])
    d.table(['quantity', 'values', 'max. relative difference'], rows, widths=[0.6, 0.15, 0.25])
    d.p('**SHA-256 of the files** (at the time this document was generated):')
    d.code('\n'.join('%-34s %s' % (f, h) for f, h in D.get('sha', {}).items()), 'text')
    for title, out, *rest in (runs or []):
        if 'ref_sm' in title:
            d.p('**Output of %s** (complete):' % title)
            d.code(out, 'text')
    return d
